// mailingC is where relationship counts are stored.
type mailingC struct {
	LastMailingMailListRecipients *int64 `json:"LastMailingMailListRecipients"`
}

// PreloadCount sets a count in the C struct by name
func (o *Mailing) PreloadCount(name string, count int64) error {
	if o == nil {
		return nil
	}

	switch name {
	case "LastMailingMailListRecipients":
		o.C.LastMailingMailListRecipients = &count
	}
	return nil
}

type mailingCountPreloader struct {
	LastMailingMailListRecipients func(...bob.Mod[*dialect.SelectQuery]) psql.Preloader
}

func buildMailingCountPreloader() mailingCountPreloader {
	return mailingCountPreloader{
		LastMailingMailListRecipients: func(mods ...bob.Mod[*dialect.SelectQuery]) psql.Preloader {
			return countPreloader[*Mailing]("LastMailingMailListRecipients", func(parent string) bob.Expression {
				// Build a correlated subquery: (SELECT COUNT(*) FROM related WHERE fk = parent.pk)
				if parent == "" {
					parent = Mailings.Alias()
				}

				subqueryMods := []bob.Mod[*dialect.SelectQuery]{
					sm.Columns(psql.Raw("count(*)")),

					sm.From(MailListRecipients.Name()),
					sm.Where(psql.Quote(MailListRecipients.Alias(), "last_mailing_id").EQ(psql.Quote(parent, "id"))),
				}
				subqueryMods = append(subqueryMods, mods...)
				return psql.Group(psql.Select(subqueryMods...).Expression)
			})
		},
	}
}

